svg.script:
(function(){
var s=document.getElementById('trains_map_tracks-svg'),g=s.querySelector('.zoom'),vb=s.viewBox.baseVal,
k=1,x=0,y=0,ptrs={},last=null;
function set(){if(!isFinite(x+y+k)){k=1;x=y=0;}x=Math.min(0,Math.max(x,vb.width*(1-k)));y=Math.min(0,Math.max(y,vb.height*(1-k)));
g.setAttribute('transform','translate('+x+' '+y+') scale('+k+')');g.style.setProperty('--k',k);
s.classList.toggle('zoomed',k>1.01);s.classList.toggle('close',k>=3);}
function pt(cx,cy){var r=s.getBoundingClientRect();return[(cx-r.left)*vb.width/r.width,(cy-r.top)*vb.height/r.height];}
function zoomAt(f,p){var n=Math.max(1,Math.min(k*f,40));f=n/k;x=p[0]-(p[0]-x)*f;y=p[1]-(p[1]-y)*f;k=n;set();}
s.addEventListener('wheel',function(e){if(!(e.ctrlKey||e.metaKey))return;e.preventDefault();
zoomAt(Math.exp(-e.deltaY*0.01),pt(e.clientX,e.clientY));},{passive:false});
s.addEventListener('dblclick',function(e){e.preventDefault();zoomAt(e.shiftKey?0.5:2,pt(e.clientX,e.clientY));});
s.addEventListener('pointerdown',function(e){if(e.target.closest('.zoom-ui'))return;ptrs[e.pointerId]=pt(e.clientX,e.clientY);
s.setPointerCapture(e.pointerId);last=null;});
s.addEventListener('pointermove',function(e){if(!(e.pointerId in ptrs))return;var p=pt(e.clientX,e.clientY),o=ptrs[e.pointerId];
ptrs[e.pointerId]=p;var ids=Object.keys(ptrs);
if(ids.length==1){if(k>1){x+=p[0]-o[0];y+=p[1]-o[1];set();}}
else if(ids.length==2){var a=ptrs[ids[0]],b=ptrs[ids[1]],d=Math.hypot(a[0]-b[0],a[1]-b[1]),
c=[(a[0]+b[0])/2,(a[1]+b[1])/2];if(last?(last.d>0?d>0:false):false){x+=c[0]-last.c[0];y+=c[1]-last.c[1];zoomAt(d/last.d,c);}last={d:d,c:c};}});
function up(e){delete ptrs[e.pointerId];last=null;}
s.addEventListener('pointerup',up);s.addEventListener('pointercancel',up);
s.querySelectorAll('.zoom-ui [data-z]').forEach(function(b){b.addEventListener('click',function(){
var z=b.getAttribute('data-z');if(z=='0'){k=1;x=y=0;set();}else zoomAt(+z,[vb.width/2,vb.height/2]);});});
set();})();
